def recherche(liste, cible):
    for i, valeur in enumerate(liste):
        if valeur == cible:
            return i
    return -1

def dichotomie(liste, cible):
    gauche, droite = 0, len(liste) - 1
    while gauche <= droite:
        milieu = (gauche + droite) // 2
        if liste[milieu] == cible:
            return milieu
        if liste[milieu] < cible:
            gauche = milieu + 1
        else:
            droite = milieu - 1
    return -1

